export const LANGUAGES = ["hu", "en", "de", "fr", "es", "ru", "ja", "zh"];
export const LANGUAGE_NAMES = {
    hu: "Magyar",
    en: "English",
    de: "Deutsch",
    fr: "Français",
    es: "Español",
    ru: "Русский",
    ja: "日本語",
    zh: "简体中文",
};
const TABLES = {
    hu: HU,
    en: EN,
    de: DE,
    fr: FR,
    es: ES,
    ru: RU,
    ja: JA,
    zh: ZH,
};
const LANGUAGE_KEY = "treevizConnectorLanguage";
const browserLanguage = () => {
    const code = navigator.language.toLowerCase().slice(0, 2);
    return LANGUAGES.includes(code)
        ? code
        : "en";
};
let language = browserLanguage();
const listeners = new Set();
const applyLanguage = (next) => {
    if (next === language) {
        return;
    }
    language = next;
    for (const listener of listeners) {
        listener();
    }
};
export const currentLanguage = () => language;
export const onLanguage = (listener) => {
    listeners.add(listener);
    return () => listeners.delete(listener);
};
const isConnectorLanguage = (value) => typeof value === "string" &&
    LANGUAGES.includes(value);
export const languageReady = new Promise((resolve) => {
    if (typeof chrome === "undefined" || !chrome.storage?.local) {
        resolve();
        return;
    }
    chrome.storage.local.get(LANGUAGE_KEY, (items) => {
        const stored = items[LANGUAGE_KEY];
        if (isConnectorLanguage(stored)) {
            applyLanguage(stored);
        }
        resolve();
    });
    chrome.storage.onChanged.addListener((changes, area) => {
        if (area !== "local" || !changes[LANGUAGE_KEY]) {
            return;
        }
        const next = changes[LANGUAGE_KEY].newValue;
        if (isConnectorLanguage(next)) {
            applyLanguage(next);
        }
    });
});
export const setLanguage = (next) => {
    applyLanguage(next);
    chrome.storage.local.set({ [LANGUAGE_KEY]: next });
};
export const t = (key, vars) => {
    let text = TABLES[language][key];
    if (vars) {
        for (const [name, value] of Object.entries(vars)) {
            text = text.replaceAll(`{{${name}}}`, value);
        }
    }
    return text;
};
